import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';

import cn from 'classnames';

import { EMainRoutes } from 'shared/typings';

import styles from './PlannerTabs.module.scss';

interface IPlannerTabsProps extends HTMLAttributes<HTMLDivElement> {
	active: '1' | '2';
}

export const PlannerTabs: FC<IPlannerTabsProps> = ({ className, active, ...props }) => {
	const { t } = useTranslation();
	const items = [
		{
			key: '1',
			label: t('Календарь'),
			to: `/${EMainRoutes.PLANNER}`,
			active: active === '1',
		},
		{
			key: '2',
			label: t('История'),
			to: `/${EMainRoutes.HISTORY}`,
			active: active === '2',
		},
	];

	return (
		<div {...props} className={cn(styles.tabs, className)}>
			{items.map((item) => (
				<Link className={cn(styles.link, { [styles.active]: item.active })} key={item.key} to={item.to}>
					{item.label}
				</Link>
			))}
		</div>
	);
};
